-- Seed of the History Card layouts (RE_MSConfiguration / SPCMSconfiguration, see HistoryCard_ConfigurationTables.sql).
-- Rows of the ThingWorx data tables RE_MSConfigurationDT / SPCMSconfiguration_DT exported 2026-10-29:
--   RE_MSConfiguration: the current rows only (ID >= 1000, entered 2025-06-13); the 2022 copy of every card is not loaded.
--   SPCMSconfiguration: the Cover LH / Cover RH rows (the only cards with an SPC table); Remarks (a "Part Paracode : ..."
--   note, not shown) is not loaded.
-- Run once in ControlTowerVLM; it deletes and reloads both tables in one transaction.

USE [ControlTowerVLM];
GO

SET XACT_ABORT ON;
BEGIN TRANSACTION;

DELETE FROM [dbo].[RE_MSConfiguration];
DELETE FROM [dbo].[SPCMSconfiguration];

-- Crank Case
-- Cover LH
-- Cover RH
-- Crank Shaft
-- Cyl Head & Cam Ladder
-- Cylinder Barrel
-- Cover LH SPC
-- Cover RH SPC

COMMIT TRANSACTION;
GO

SELECT 'RE_MSConfiguration' AS [Table], COUNT(*) AS [Rows] FROM [dbo].[RE_MSConfiguration]   -- expect 386
UNION ALL SELECT 'SPCMSconfiguration', COUNT(*) FROM [dbo].[SPCMSconfiguration];             -- expect 117
GO
